import requests


class CusBuild(object):

    def __init__(self, device, proxy=None):
        self.device = device
        self.proxy = proxy
        self.json_url = 'http://wrihtdv01.emea.nsn-net.net/view/CUS%20Applications/job/Full%20Package%20' \
                        '(AirScale,%20DEB9)/lastSuccessfulBuild/api/json?tree=artifacts[relativePath]'
        self.package_name = self.get_cus_build_name()
        self.url_link = 'http://wrihtdv01.emea.nsn-net.net/job/Full%20Package%20(AirScale,%20DEB9)/' \
                        'lastSuccessfulBuild/artifact/{}'.format(self.package_name)
        self.local_build_path = '/tmp/{}'.format(self.package_name)

    def get_cus_build_name(self):
        result = requests.get(self.json_url)
        return result.json()['artifacts'][0]['relativePath']

    def download_cus_build(self):
        download_options = self.get_download_options()
        download_build_cmd = self.device.get_cmd(cmd_name="wget", cmd_params={"options": download_options})
        download_build_cmd(1800)

    def get_download_options(self):
        link_with_options = "'{}' -O {}".format(self.url_link, self.local_build_path)
        if self.proxy:
            link_with_options = "{} -e use_proxy=yes -e http_proxy={}".format(link_with_options, self.proxy)
        return link_with_options
